CREATE TABLE plans (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, name VARCHAR(80) NOT NULL, description TEXT NOT NULL, price INT NULL, currency VARCHAR(8) NOT NULL DEFAULT 'COP', period VARCHAR(8) NOT NULL DEFAULT 'month', highlights JSON NOT NULL, features JSON NOT NULL, limits JSON NOT NULL, is_default INT NOT NULL DEFAULT 0, active INT NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), CONSTRAINT plans_price_ck CHECK (price IS NULL OR price>=0), CONSTRAINT plans_period_ck CHECK (period IN ('free','month','year','once')), CONSTRAINT plans_default_ck CHECK (is_default IN (0,1)), CONSTRAINT plans_active_ck CHECK (active IN (0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci